sp_widget.client_script:
api.controller = function($scope, $sce) {
    var c = this;

    // =====================================================
    // INITIAL STATE & AI PANEL VARIABLES
    // =====================================================
    c.showAIPanel = false;
    c.loadingAI = false;
    c.aiSummaryHtml = "";
    c.activeStudentName = "";
    c.currentFilter = "ALL";
    c.searchQuery = "";
    c.selectedCase = null;

    // =====================================================
    // TRIGGER AI CASE SUMMARY
    // =====================================================
    c.generateSummary = function(sysId, studentName) {
        c.showAIPanel = true;
        c.loadingAI = true;
        c.activeStudentName = studentName;
        c.aiSummaryHtml = "";

        // Smoothly scroll down to the AI Panel
        setTimeout(function() {
            var el = document.querySelector('.ai-detail-panel');
            if(el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }, 150);

        // Call the Script Include via GlideAjax
        var ga = new GlideAjax('x_snc_visaguardi_0.VisaGuardianAIUtils');
        ga.addParam('sysparm_name', 'generateCaseSummary');
        ga.addParam('sysparm_case_id', sysId);

        ga.getXMLAnswer(function(response) {
            c.loadingAI = false;
            console.log("AI Backend Response:", response);

            try {
                var result = JSON.parse(response);

                if (result.success) {
                    // Clean and parse Markdown into formatted HTML
                    var rawText = result.content;
                    var formattedHtml = rawText
                        .replace(/^#### (.*?)$/gm, '<h5 style="color:#475569; margin-top:20px; margin-bottom:10px; font-weight:600;">$1</h5>')
                        .replace(/^### (.*?)$/gm, '<h4>$1</h4>')
                        .replace(/^## (.*?)$/gm, '<h3>$1</h3>')
                        .replace(/^# (.*?)$/gm, '<h2>$1</h2>')
                        .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                        .replace(/`(.*?)`/g, '<span style="background-color:#f1f5f9; border:1px solid #e2e8f0; padding:2px 6px; border-radius:4px; font-family:monospace; font-size:0.9em; color:#e11d48;">$1</span>')
                        .replace(/^- \[\s?\] (.*?)$/gm, '<div style="margin-left:15px; margin-bottom:6px;"><i class="fa fa-square-o" style="color:#94a3b8; margin-right:8px; font-size:1.1em;"></i>$1</div>')
                        .replace(/^- \[[xX]\] (.*?)$/gm, '<div style="margin-left:15px; margin-bottom:6px;"><i class="fa fa-check-square" style="color:#10b981; margin-right:8px; font-size:1.1em;"></i>$1</div>')
                        .replace(/^[-*] (.*?)$/gm, '<li style="margin-left:25px; margin-bottom:5px;">$1</li>')
                        .replace(/> \[!WARNING\]/g, '<strong><i class="fa fa-exclamation-triangle" style="color:#d97706;"></i> WARNING:</strong>')
                        .replace(/^> (.*?)$/gm, '<div style="border-left:4px solid #f59e0b; background:#fef3c7; padding:12px; margin:15px 0; border-radius:0 6px 6px 0; color:#92400e;">$1</div>')
                        .replace(/✓ (.*?)$/gm, '<span class="source-chip">✓ $1</span>')
                        .replace(/^\|(.*)\|$/gm, '<div style="padding:4px 0; border-bottom:1px solid #f1f5f9;">$1</div>')
                        .replace(/---/g, '<hr style="margin:20px 0; border-top:1px solid #e2e8f0;"/>')
                        .replace(/\n/g, '<br/>')
                        .replace(/(<br\/>)+<li/g, '<li')
                        .replace(/<\/li>(<br\/>)+/g, '</li>')
                        .replace(/(<br\/>)+<div/g, '<div')
                        .replace(/<\/div>(<br\/>)+/g, '</div>');

                    c.aiSummaryHtml = $sce.trustAsHtml(formattedHtml);
                } else {
                    c.aiSummaryHtml = $sce.trustAsHtml("<div class='alert alert-danger'>AI Error: " + result.error + "</div>");
                }
            } catch(e) {
                c.aiSummaryHtml = $sce.trustAsHtml("<div class='alert alert-danger'>Failed to process AI response.</div>");
            }

            $scope.$apply(); 
        });
    };

    // Close the AI panel
    c.closeAIPanel = function() {
        c.showAIPanel = false;
        c.activeStudentName = "";
    };

    // =====================================================
    // METRICS & COUNTERS
    // =====================================================
    c.getHighRiskCount = function() {
        return Number(c.data.high_risk_count || 0);
    };

    c.getMediumRiskCount = function() {
        return Number(c.data.medium_risk_count || 0);
    };

    c.getComplianceRate = function() {
        return Number(c.data.compliance_rate || 0) + "%";
    };

    // =====================================================
    // FILTERS & SEARCH
    // =====================================================
    c.setFilter = function(filter) {
        c.currentFilter = filter;
    };

    c.filterCases = function(item) {
        if (!item) return false;

        if (c.currentFilter === "High" && item.risk_level !== "High") return false;
        if (c.currentFilter === "Medium" && item.risk_level !== "Medium") return false;
        if (c.currentFilter === "Compliant" && item.risk_level !== "Low") return false;

        var query = String(c.searchQuery || "").toLowerCase().trim();
        if (!query) return true;

        return (
            String(item.student_name || "").toLowerCase().indexOf(query) >= 0 ||
            String(item.student_id || "").toLowerCase().indexOf(query) >= 0 ||
            String(item.category || "").toLowerCase().indexOf(query) >= 0 ||
            String(item.rule_title || "").toLowerCase().indexOf(query) >= 0
        );
    };

    // =====================================================
    // MODAL AUDIT FUNCTIONS
    // =====================================================
    c.openAuditModal = function(item) {
        c.selectedCase = angular.copy(item);
        $timeout(function() {
            if (typeof jQuery !== "undefined") {
                jQuery("#riskAuditModal").modal("show");
            }
        }, 100);
    };

    c.closeAuditModal = function() {
        if (typeof jQuery !== "undefined") {
            jQuery("#riskAuditModal").modal("hide");
        }
        c.selectedCase = null;
    };

    c.exportReport = function() {
        c.server.update().then(function(response) {
            c.data = response.data;
        });
    };

    c.updateStatus = function(status) {
        if (!c.selectedCase || !c.selectedCase.sys_id) return;

        c.server.get({
            action: "update_status",
            sys_id: c.selectedCase.sys_id,
            new_status: status
        }).then(function(response) {
            c.data = response.data;
            c.selectedCase = null;
            $timeout(function() {
                if (typeof jQuery !== "undefined") {
                    jQuery("#riskAuditModal").modal("hide");
                }
            }, 100);
        });
    };
};

sp_widget.css:
/* =========================================================
   VISAGUARDIAN AI
   ADVISOR RISK & COMPLIANCE
   PREMIUM ENTERPRISE UI
   ========================================================= */


/* =========================================================
   GLOBAL WORKSPACE
   ========================================================= */

.vg-workspace-container {

    width: 100%;
    min-height: 100vh;

    margin: 0;
    padding: 0;

    box-sizing: border-box;

    background: #f5f8fc;

    color: #183b63;

    font-family:
        "Segoe UI",
        -apple-system,
        BlinkMacSystemFont,
        "Helvetica Neue",
        Arial,
        sans-serif;
}


/* =========================================================
   HERO BANNER
   ========================================================= */

.vg-workspace-container .vg-hero-banner {

    position: relative;

    width: 100%;

    display: flex;

    align-items: center;

    justify-content: space-between;

    box-sizing: border-box;

    overflow: hidden;

    padding: 30px 38px;

    margin: 0 0 24px 0;

    background:
        linear-gradient(
            135deg,
            #132e5b 0%,
            #173f76 48%,
            #1768a8 100%
        );

    color: #ffffff;

    border-radius: 0 0 16px 16px;

    border:
        1px solid
        rgba(255,255,255,.08);

    box-shadow:
        0 10px 28px
        rgba(18,56,99,.18);
}


/* Decorative glow */

.vg-workspace-container .vg-hero-banner::before {

    content: "";

    position: absolute;

    width: 360px;
    height: 360px;

    right: -170px;
    top: -220px;

    border-radius: 50%;

    background:
        rgba(87,173,255,.10);

    pointer-events: none;
}


.vg-workspace-container .vg-hero-banner::after {

    content: "";

    position: absolute;

    width: 220px;
    height: 220px;

    right: 28%;
    bottom: -190px;

    border-radius: 50%;

    background:
        rgba(255,255,255,.035);

    pointer-events: none;
}


/* =========================================================
   HERO CONTENT
   ========================================================= */

.vg-workspace-container .hero-content {

    position: relative;

    z-index: 2;

    display: flex;

    align-items: center;

    gap: 18px;
}


.vg-workspace-container .hero-content h2 {

    margin:
        0 0 5px 0;

    color:
        #ffffff;

    font-size:
        28px;

    line-height:
        34px;

    font-weight:
        750;

    letter-spacing:
        -.4px;
}


.vg-workspace-container .hero-content p {

    margin:
        0;

    color:
        rgba(255,255,255,.80);

    font-size:
        14px;

    line-height:
        20px;

    font-weight:
        500;
}


/* =========================================================
   HERO ACTIONS
   ========================================================= */

.vg-workspace-container .hero-actions {

    position:
        relative;

    z-index:
        2;

    flex-shrink:
        0;
}


.vg-workspace-container .btn-hero-outline {

    min-height:
        42px;

    display:
        inline-flex;

    align-items:
        center;

    justify-content:
        center;

    padding:
        9px 18px;

    background:
        rgba(255,255,255,.08);

    border:
        1px solid
        rgba(255,255,255,.35);

    color:
        #ffffff;

    border-radius:
        9px;

    font-size:
        12px;

    font-weight:
        700;

    transition:
        all .2s ease;
}


.vg-workspace-container .btn-hero-outline:hover {

    background:
        #ffffff;

    border-color:
        #ffffff;

    color:
        #174678;

    transform:
        translateY(-1px);

    box-shadow:
        0 5px 14px
        rgba(0,0,0,.12);
}


/* =========================================================
   METRIC ROW
   ========================================================= */

.vg-workspace-container .metric-row {

    margin:
        0 0 4px 0;
}


/* =========================================================
   METRIC CARD
   ========================================================= */

.vg-workspace-container .vg-metric-card {

    position:
        relative;

    min-height:
        122px;

    display:
        flex;

    align-items:
        center;

    gap:
        17px;

    padding:
        22px;

    box-sizing:
        border-box;

    background:
        #ffffff;

    border:
        1px solid
        #dfe7f0;

    border-radius:
        14px;

    box-shadow:
        0 6px 20px
        rgba(27,62,99,.055);

    transition:
        transform .2s ease,
        box-shadow .2s ease,
        border-color .2s ease;
}


.vg-workspace-container .vg-metric-card:hover {

    transform:
        translateY(-3px);

    border-color:
        #cbd9e7;

    box-shadow:
        0 12px 27px
        rgba(27,62,99,.10);
}


/* =========================================================
   METRIC ICON
   ========================================================= */

.vg-workspace-container .metric-icon {

    width:
        56px;

    height:
        56px;

    min-width:
        56px;

    display:
        flex;

    align-items:
        center;

    justify-content:
        center;

    border-radius:
        15px;

    font-size:
        21px;

    flex-shrink:
        0;
}


/* HIGH RISK */

.vg-workspace-container .red-circle {

    background:
        linear-gradient(
            145deg,
            #fff2f2,
            #ffebeb
        );

    color:
        #dc2626;

    border:
        1px solid
        #f4d0d0;
}


/* PENDING */

.vg-workspace-container .orange-circle {

    background:
        linear-gradient(
            145deg,
            #fff8ec,
            #fff2df
        );

    color:
        #ea580c;

    border:
        1px solid
        #f6dfbf;
}


/* COMPLIANT */

.vg-workspace-container .green-circle {

    background:
        linear-gradient(
            145deg,
            #effcf5,
            #e5f9ee
        );

    color:
        #15965a;

    border:
        1px solid
        #cdeedc;
}


/* BLUE */

.vg-workspace-container .blue-circle {

    background:
        linear-gradient(
            145deg,
            #edf5ff,
            #e4efff
        );

    color:
        #2563eb;

    border:
        1px solid
        #d7e7ff;
}


/* =========================================================
   METRIC DATA
   ========================================================= */

.vg-workspace-container .metric-data {

    display:
        flex;

    flex-direction:
        column;

    min-width:
        0;
}


.vg-workspace-container .metric-number {

    font-size:
        29px;

    line-height:
        1;

    margin:
        0 0 6px 0;

    font-weight:
        750;

    letter-spacing:
        -.6px;
}


.vg-workspace-container .metric-label {

    margin:
        0 0 4px 0;

    color:
        #71839a;

    font-size:
        10px;

    font-weight:
        750;

    text-transform:
        uppercase;

    letter-spacing:
        .7px;
}


.vg-workspace-container .metric-subtext {

    margin:
        0;

    font-size:
        11px;

    font-weight:
        650;
}


/* =========================================================
   STANDARD COLORS
   ========================================================= */

.vg-workspace-container .text-blue {

    color:
        #2563eb !important;
}


.vg-workspace-container .text-orange {

    color:
        #ea580c !important;
}


.vg-workspace-container .text-green {

    color:
        #15965a !important;
}


.vg-workspace-container .text-red {

    color:
        #dc2626 !important;
}


.vg-workspace-container .text-white {

    color:
        #ffffff !important;
}


.vg-workspace-container .font-bold {

    font-weight:
        750;
}


/* =========================================================
   MAIN CARD
   ========================================================= */

.vg-workspace-container .vg-card {

    width:
        100%;

    background:
        #ffffff;

    border:
        1px solid
        #dce6f0;

    border-radius:
        15px;

    box-shadow:
        0 6px 20px
        rgba(27,62,99,.055);

    padding:
        22px 26px;

    box-sizing:
        border-box;

    transition:
        box-shadow .2s ease,
        border-color .2s ease;
}


.vg-workspace-container .vg-card:hover {

    border-color:
        #d1dfeb;

    box-shadow:
        0 9px 25px
        rgba(27,62,99,.075);
}


.vg-workspace-container .margin-top-lg {

    margin-top:
        22px;
}


/* =========================================================
   CARD HEADER
   ========================================================= */

.vg-workspace-container .vg-card-header {

    display:
        flex;

    align-items:
        center;

    justify-content:
        space-between;

    padding:
        0 0 17px 0;

    margin:
        0 0 17px 0;

    border-bottom:
        1px solid
        #e5edf4;

    flex-wrap:
        wrap;

    gap:
        14px;
}


.vg-workspace-container .vg-card-header h4 {

    margin:
        0;

    color:
        #123f70;

    font-size:
        19px;

    line-height:
        1.3;

    font-weight:
        750;

    letter-spacing:
        -.25px;
}


.vg-workspace-container .vg-card-header h4 i {

    display:
        inline-flex;

    align-items:
        center;

    justify-content:
        center;

    width:
        28px;

    height:
        28px;

    margin-right:
        8px;

    border-radius:
        8px;

    background:
        #edf5ff;

    color:
        #2563eb;

    font-size:
        14px;
}


.vg-workspace-container .header-right {

    display:
        flex;

    align-items:
        center;

    justify-content:
        flex-end;

    gap:
        10px;

    flex-wrap:
        wrap;
}


/* =========================================================
   FILTER PILLS
   ========================================================= */

.vg-workspace-container .filter-pills {

    display:
        flex;

    align-items:
        center;

    gap:
        3px;

    padding:
        4px;

    background:
        #f1f5f9;

    border:
        1px solid
        #e4eaf1;

    border-radius:
        9px;
}


.vg-workspace-container .filter-pills .btn {

    min-height:
        36px;

    padding:
        7px 14px;

    background:
        transparent;

    border:
        1px solid
        transparent;

    color:
        #64778c;

    border-radius:
        7px;

    font-size:
        11px;

    font-weight:
        650;

    transition:
        all .2s ease;
}


.vg-workspace-container .filter-pills .btn:hover {

    background:
        #ffffff;

    color:
        #2563eb;

    border-color:
        #e0e8f1;
}


.vg-workspace-container .filter-pills .btn.active {

    background:
        linear-gradient(
            135deg,
            #2563eb,
            #2f70dd
        );

    color:
        #ffffff;

    border-color:
        #2563eb;

    box-shadow:
        0 3px 8px
        rgba(37,99,235,.20);
}


/* =========================================================
   SEARCH
   ========================================================= */

.vg-workspace-container .search-wrapper {

    position:
        relative;

    width:
        260px;
}


.vg-workspace-container .search-icon {

    position:
        absolute;

    left:
        12px;

    top:
        50%;

    transform:
        translateY(-50%);

    color:
        #9aaabd;

    font-size:
        13px;

    pointer-events:
        none;

    z-index:
        2;
}


.vg-workspace-container .search-input {

    width:
        100%;

    height:
        40px;

    padding:
        8px 12px 8px 34px;

    box-sizing:
        border-box;

    background:
        #ffffff;

    border:
        1px solid
        #cedae6;

    border-radius:
        8px;

    color:
        #183b63;

    font-size:
        12px;

    outline:
        none;

    transition:
        all .2s ease;
}


.vg-workspace-container .search-input::placeholder {

    color:
        #9aaabd;
}


.vg-workspace-container .search-input:hover {

    border-color:
        #b9cbdc;
}


.vg-workspace-container .search-input:focus {

    border-color:
        #2563eb;

    box-shadow:
        0 0 0 3px
        rgba(37,99,235,.09);
}


/* =========================================================
   TABLE
   ========================================================= */

.vg-workspace-container .vg-table {

    width:
        100%;

    min-width:
        1050px;

    margin:
        0;

    border-collapse:
        separate;

    border-spacing:
        0;
}


.vg-workspace-container .vg-table th {

    padding:
        14px 10px;

    background:
        #f7fafd;

    color:
        #63778d;

    font-size:
        10px;

    font-weight:
        750;

    text-transform:
        uppercase;

    letter-spacing:
        .7px;

    border-bottom:
        1px solid
        #dfe7ef;

    white-space:
        nowrap;
}


.vg-workspace-container .vg-table td {

    padding:
        16px 10px;

    vertical-align:
        middle;

    color:
        #37516b;

    font-size:
        13px;

    border-bottom:
        1px solid
        #edf2f6;

    background:
        #ffffff;
}


.vg-workspace-container .vg-table tbody tr {

    transition:
        background .15s ease;
}


.vg-workspace-container .vg-table tbody tr:hover td {

    background:
        #f8fbff;
}


.vg-workspace-container .vg-table tbody tr:last-child td {

    border-bottom:
        none;
}


/* =========================================================
   STUDENT
   ========================================================= */

.vg-workspace-container .student-cell {

    display:
        flex;

    flex-direction:
        column;

    gap:
        4px;
}


.vg-workspace-container .student-name {

    color:
        #143d67;

    font-size:
        14px;

    font-weight:
        700;
}


.vg-workspace-container .student-id {

    margin-top:
        0;

    color:
        #7b8ea2;

    font-size:
        11px;

    font-weight:
        500;
}


/* =========================================================
   CATEGORY
   ========================================================= */

.vg-workspace-container .category-badge {

    display:
        inline-flex;

    align-items:
        center;

    padding:
        6px 10px;

    background:
        #eef4ff;

    color:
        #2458c4;

    border:
        1px solid
        #d9e7ff;

    border-radius:
        7px;

    font-size:
        11px;

    font-weight:
        700;

    white-space:
        nowrap;
}


/* =========================================================
   RULE / FLAG
   ========================================================= */

.vg-workspace-container .rule-title {

    display:
        inline-flex;

    align-items:
        center;

    gap:
        6px;

    color:
        #36536e;

    font-size:
        12px;

    font-weight:
        600;

    white-space:
        nowrap;
}


/* =========================================================
   DEADLINE
   ========================================================= */

.vg-workspace-container .deadline-tag {

    display:
        inline-flex;

    align-items:
        center;

    gap:
        6px;

    color:
        #58738d;

    font-size:
        12px;

    font-weight:
        500;

    white-space:
        nowrap;
}


.vg-workspace-container .deadline-tag i {

    color:
        #2563eb;
}


/* =========================================================
   RISK SCORE
   ========================================================= */

.vg-workspace-container .risk-score-pill {

    display:
        inline-flex;

    align-items:
        center;

    justify-content:
        center;

    padding:
        7px 10px;

    border-radius:
        7px;

    font-size:
        11px;

    font-weight:
        750;

    white-space:
        nowrap;
}


/* HIGH */

.vg-workspace-container .risk-high {

    background:
        #fff0f0;

    color:
        #c62828;

    border:
        1px solid
        #f4cccc;
}


/* MEDIUM */

.vg-workspace-container .risk-medium {

    background:
        #fff8e9;

    color:
        #a86b09;

    border:
        1px solid
        #f2dba9;
}


/* LOW */

.vg-workspace-container .risk-low {

    background:
        #eaf9f1;

    color:
        #087b4e;

    border:
        1px solid
        #c5ecd8;
}


/* =========================================================
   STATUS
   ========================================================= */

.vg-workspace-container .status-pill {

    display:
        inline-flex;

    align-items:
        center;

    justify-content:
        center;

    padding:
        7px 11px;

    border-radius:
        20px;

    font-size:
        11px;

    font-weight:
        700;

    white-space:
        nowrap;
}


/* RED */

.vg-workspace-container .pill-red {

    background:
        #fff0f0;

    color:
        #b42323;

