sp_widget.script:
(function() {

    data.risk_cases = [];
    data.high_risk_count = 0;
    data.medium_risk_count = 0;
    data.low_risk_count = 0;
    data.compliance_rate = 0;
    data.error = "";

    // =====================================================
    // GET CURRENT ADVISOR
    // SAME LOGIC AS WORKING ADVISOR DASHBOARD
    // =====================================================

    var userSysId = gs.getUserID();

    var sessionAdvisorSysId =
        gs.getSession().getClientData("vg_advisor_sys_id");

    if (sessionAdvisorSysId) {
        userSysId = sessionAdvisorSysId;
    }

    if (!userSysId) {
        data.error = "Advisor could not be identified.";
        return;
    }


    // =====================================================
    // GET EXACT SAME CASES AS ADVISOR DASHBOARD
    // =====================================================

    var caseGR = new GlideRecord(
        "x_snc_visaguardi_0_visa_case"
    );

    caseGR.addQuery(
        "advisor",
        userSysId
    );

    caseGR.orderByDesc(
        "sys_created_on"
    );

    caseGR.query();


    // =====================================================
    // PROCESS EVERY ADVISOR CASE
    // =====================================================

    while (caseGR.next()) {

        var studentSysId =
            caseGR.getValue("student");

        var studentName =
            caseGR.getDisplayValue("student") ||
            "Unknown Student";

        var studentId =
            "N/A";


        // =================================================
        // GET STUDENT PROFILE
        // =================================================

        if (studentSysId) {

            var studentGR = new GlideRecord(
                "x_snc_visaguardi_0_student_profile"
            );

            if (studentGR.get(studentSysId)) {

                studentId =
                    studentGR.getValue("student_id") ||
                    "N/A";

                var profileName =
                    studentGR.getValue("name") || "";

                if (profileName) {
                    studentName = profileName;
                }
                else {

                    var firstName =
                        studentGR.getValue("first_name") || "";

                    var lastName =
                        studentGR.getValue("last_name") || "";

                    var fullName =
                        (
                            firstName +
                            " " +
                            lastName
                        ).trim();

                    if (fullName) {
                        studentName = fullName;
                    }
                }
            }
        }


        // =================================================
        // CASE TYPE
        // =================================================

        var category =
            caseGR.getDisplayValue("case_type") ||
            "Visa Case";


        // =================================================
        // CASE STAGE
        // =================================================

        var caseStage =
            caseGR.getDisplayValue("case_stage") ||
            "N/A";


        // =================================================
        // STATUS
        // =================================================

        var status =
            caseGR.getDisplayValue("status") ||
            caseStage ||
            "Under Review";


        // =================================================
        // SIMPLE RISK CALCULATION
        // =================================================

        var riskScore = 30;

        var riskLevel = "Low";


        // Case stage based risk

        var stage =
            String(caseStage).toLowerCase();


        if (
            stage.indexOf("pending") >= 0
        ) {

            riskScore = 55;

        }


        if (
            stage.indexOf("review") >= 0
        ) {

            riskScore = 65;

        }


        if (
            stage.indexOf("risk") >= 0 ||
            stage.indexOf("urgent") >= 0
        ) {

            riskScore = 80;

        }


        // Status based risk

        var statusLower =
            String(status).toLowerCase();


        if (
            statusLower.indexOf("pending") >= 0
        ) {

            riskScore = Math.max(
                riskScore,
                55
            );

        }


        if (
            statusLower.indexOf("review") >= 0
        ) {

            riskScore = Math.max(
                riskScore,
                65
            );

        }


        if (
            statusLower.indexOf("resolved") >= 0 ||
            statusLower.indexOf("completed") >= 0 ||
            statusLower.indexOf("closed") >= 0
        ) {

            riskScore = 15;

        }


        // =================================================
        // RISK LEVEL
        // =================================================

        if (riskScore >= 70) {

            riskLevel = "High";

        }
        else if (riskScore >= 40) {

            riskLevel = "Medium";

        }
        else {

            riskLevel = "Low";

        }


        // =================================================
        // RULE
        // =================================================

        var ruleTitle =
            "Routine compliance monitoring";


        if (riskLevel === "High") {

            ruleTitle =
                "High risk compliance review";

        }
        else if (riskLevel === "Medium") {

            ruleTitle =
                "Compliance review required";

        }


        // =================================================
        // DEADLINE
        // =================================================

        var deadline =
            "No deadline";

        var daysLeft =
            999;


        if (
            caseGR.isValidField("due_date") &&
            caseGR.getValue("due_date")
        ) {

            deadline =
                caseGR.getDisplayValue("due_date");


            var due =
                new GlideDateTime(
                    caseGR.getValue("due_date")
                );

            var now =
                new GlideDateTime();


            var diff =
                due.getNumericValue() -
                now.getNumericValue();


            daysLeft =
                Math.ceil(
                    diff /
                    86400000
                );


            if (daysLeft < 0) {

                riskScore = 90;
                riskLevel = "High";

                ruleTitle =
                    "SEVIS deadline overdue";

            }
            else if (daysLeft <= 5) {

                riskScore =
                    Math.max(
                        riskScore,
                        75
                    );

                riskLevel = "High";

                ruleTitle =
                    "SEVIS deadline approaching";

            }

        }


        // =================================================
        // DESCRIPTION
        // =================================================

        var description =
            "This advisor case requires compliance monitoring.";


        if (riskLevel === "High") {

            description =
                "This case requires immediate advisor attention.";

        }
        else if (riskLevel === "Medium") {

            description =
                "This case requires additional compliance review.";

        }


        // =================================================
        // RECOMMENDATION
        // =================================================

        var recommendation =
            "Review the case and verify all required student documentation.";


        if (riskLevel === "High") {

            recommendation =
                "Perform an immediate compliance review and document the required advisor action.";

        }
        else if (riskLevel === "Medium") {

            recommendation =
                "Review the case and monitor the student's compliance requirements.";

        }


        // =================================================
        // PUSH CASE
        // =================================================

        data.risk_cases.push({

            sys_id:
                caseGR.getUniqueValue(),

            student_name:
                studentName,

            student_id:
                studentId,

            category:
                category,

            rule_title:
                ruleTitle,

            risk_score:
                riskScore,

            risk_level:
                riskLevel,

            deadline:
                deadline,

            days_left:
                daysLeft,

            status:
                status,

            case_stage:
                caseStage,

            description:
                description,

            recommendation:
                recommendation,

            advisor:
                caseGR.getDisplayValue("advisor")

        });


        // =================================================
        // COUNTERS
        // =================================================

        if (riskLevel === "High") {

            data.high_risk_count++;

        }
        else if (riskLevel === "Medium") {

            data.medium_risk_count++;

        }
        else {

            data.low_risk_count++;

        }

    }


    // =====================================================
    // COMPLIANCE RATE
    // =====================================================

    if (data.risk_cases.length > 0) {

        data.compliance_rate =
            Math.round(
                (
                    data.low_risk_count /
                    data.risk_cases.length
                ) * 100
            );

    }
    else {

        data.compliance_rate = 0;

    }


    // =====================================================
    // DEBUG
    // =====================================================

    data.debug = {

        advisor_sys_id:
            userSysId,

        advisor_name:
            gs.getUserName(),

        session_advisor:
            sessionAdvisorSysId || "",

        total_cases:
            data.risk_cases.length

    };

})();
